import requests
from bs4 import BeautifulSoup

def translate_html(html_content, target_language='es'):
    # Parse the HTML content
    soup = BeautifulSoup(html_content, 'html.parser')

    # Function to translate text content
    def translate_text(text):
        # Translate the text content using Azure AI Translator
        response = requests.post(
            'https://api.cognitive.azure.com/translator/text/v3.0/translate',
            headers={
                'Ocp-Apim-Subscription-Key': 'YOUR_AZURE_TRANSLATOR_KEY',
                'Ocp-Apim-Subscription-Region': 'YOUR_AZURE_REGION',
                'Content-Type': 'application/json',
            },
            json=[{'text': text, 'to': target_language}],
        )
        data = response.json()
        return data[0]['translations'][0]['text']

    # Function to recursively translate text content within HTML tags
    def translate_html_content(element):
        if element.string and element.string.strip():
            element.string.replace_with(translate_text(element.string))
        for child in element.children:
            if child.name:
                translate_html_content(child)

    # Start translation from the root element
    translate_html_content(soup)

    # Return the translated HTML content
    return str(soup)
